:root {
  /* Colors */
  --color-paper-canvas: #fbfbf9;
  --color-chalk-white: #ffffff;
  --color-linen-panel: #f5f2f0;
  --color-stone-panel: #efeeec;
  --color-sand-panel: #f0eae5;
  --color-clay-tab: #e3d7cd;
  --color-frosted-nav: #fbfbf9d9;
  --color-ink: #1e1e1e;
  --color-pewter-caption: #777777;
  --color-cream-ink: #f0e9e5;
  --color-quartz-track: #d0d5d2;
  --color-ember-signal: #ee884f;
  --color-periwinkle-wash: #9da5c7;

  /* Typography — Font Families */
  --font-archivo: "Archivo", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.4;
  --tracking-small: 0.66px;
  --text-caption: 14px;
  --leading-caption: 1.2;
  --tracking-caption: -0.14px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.3;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.3;
  --tracking-body-lg: 0px;
  --text-heading-sm: 36px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -1.08px;
  --text-heading: 44px;
  --leading-heading: 1.0;
  --tracking-heading: -1.32px;
  --text-heading-lg: 52px;
  --leading-heading-lg: 1.0;
  --tracking-heading-lg: -1.56px;
  --text-display: 68px;
  --leading-display: 0.9;
  --tracking-display: -2.04px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-40: 40px;
  --spacing-52: 52px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-88: 88px;
  --spacing-120: 120px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1264px;
  --layout-section-gap: 128px;
  --layout-card-padding: 24px;
  --layout-element-gap: 24px;
  --layout-nav-height: 88px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 50px;
  --radius-full: 4800px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-buttons: 4px;
  --radius-cards: 6px;
  --radius-inputs: 50px;
  --radius-pills: 4800px;
  --radius-avatars: 4800px;
  --radius-sections: 0px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0) 0px 5px 2px 0px, rgba(0, 0, 0, 0.01) 0px 4px 1px 0px, rgba(0, 0, 0, 0.04) 0px 2px 1px 0px, rgba(0, 0, 0, 0.06) 0px 1px 1px 0px;
  --shadow-md: rgba(172, 171, 171, 0.3) 0px -1px 10px 0px;
  --shadow-xl: rgba(0, 0, 0, 0.3) 0px 32px 68px 0px;

  /* Surfaces */
  --surface-paper-canvas: #fbfbf9;
  --surface-linen-panel: #f5f2f0;
  --surface-sand-panel: #f0eae5;
  --surface-chalk-white: #ffffff;
  --surface-ink: #1e1e1e;
}

